.muted { color: var(--muted); }.faint{color:var(--faint)}
.pos { color: var(--green) !important; }.neg { color: var(--red) !important; }.flat{color:#ccd2dc!important}
.badge { display: inline-flex; align-items: center; gap: 5px; border-radius: 999px; padding: 3px 8px; font-size: 12px; font-weight: 800; background: rgba(255,255,255,.07); }
.badge.pos { background: rgba(0,192,118,.12); }.badge.neg{background:rgba(247,82,95,.12)}.badge.blue{color:#bfcfff;background:rgba(41,98,255,.15)}
.section { padding: 22px 0; }
.section-head { display: flex; align-items: end; justify-content: space-between; gap: 16px; margin-bottom: 14px; }
h2 { margin: 0; font-size: 26px; letter-spacing: -.04em; } h3 { margin: 0; font-size: 17px; letter-spacing: -.02em; }
.section-head p { margin: 6px 0 0; color: var(--muted); }
.tabbar { display: flex; gap: 7px; flex-wrap: wrap; }
.tab { border: 1px solid var(--line); color: var(--muted); background: rgba(255,255,255,.035); border-radius: 999px; padding: 8px 12px; cursor: pointer; font-weight: 800; }
.tab.active { color: #fff; background: rgba(41,98,255,.22); border-color: rgba(41,98,255,.55); box-shadow: inset 0 0 0 1px rgba(255,255,255,.04); }
.tab-panel { display: none; }.tab-panel.active { display: block; animation: fade .22s ease; }
@keyframes fade { from { opacity: 0; transform: translateY(5px);} to{opacity:1;transform:none;} }
.market-strip { display: grid; grid-template-columns: repeat(6, minmax(150px, 1fr)); gap: 10px; }
.stat-card { padding: 14px; border-radius: 13px; background: rgba(255,255,255,.045); border: 1px solid var(--line); min-height: 92px; }
.stat-top { display:flex; justify-content:space-between; gap:8px; color:var(--muted); font-size:12px; }
.stat-value { margin-top: 10px; font-family: var(--mono); font-size: 20px; font-weight: 850; }
.stat-sub { margin-top: 6px; font-size: 12px; color: var(--muted); }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; }.grid-2{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.grid-4{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}
.card { padding: 16px; }
.idea-card { min-height: 238px; display: flex; flex-direction: column; justify-content: space-between; position: relative; overflow: hidden; }
.idea-chart { height: 92px; margin: 12px 0; border-radius: 10px; background: #0d111d; border: 1px solid var(--line); overflow: hidden; }
.meta { display: flex; align-items:center; gap: 8px; color: var(--muted); font-size: 12px; flex-wrap: wrap; }
.table-card { overflow: hidden; }
table { width: 100%; border-collapse: collapse; }
th, td { padding: 11px 13px; text-align: left; border-bottom: 1px solid var(--line); white-space: nowrap; }
th { color: var(--muted); font-size: 12px; font-weight: 750; background: rgba(255,255,255,.035); }
td { font-family: var(--mono); } td:first-child, th:first-child { font-family: var(--sans); }
footer { margin-top: 28px; border-top: 1px solid var(--line); background: rgba(0,0,0,.24); padding: 28px 0; }
.footer-grid { display:grid; grid-template-columns: repeat(6,1fr); gap:18px; } footer h4{margin:0 0 10px;font-size:13px} footer a, footer p{display:block;color:var(--muted);margin:7px 0;font-size:13px}.fine{margin-top:20px;color:var(--faint);font-size:12px}
/* Chart workspace */
.chart-page { height: calc(100vh - 64px); overflow: hidden; }
.workspace { display: grid; grid-template-columns: 76px 1fr 330px; height: 100%; }
.tool-rail { border-right: 1px solid var(--line); background: #0d1018; display: flex; flex-direction: column; align-items: center; gap: 9px; padding: 12px 8px; }
.tool { width: 42px; height: 42px; border-radius: 11px; border: 1px solid var(--line); background: rgba(255,255,255,.04); color: var(--muted); display:grid;place-items:center; cursor:pointer; }
.tool:hover,.tool.active{color:#fff;background:rgba(41,98,255,.18);border-color:rgba(41,98,255,.45)}
.chart-main { min-width: 0; display: grid; grid-template-rows: auto 1fr 238px; background: #0b0e17; }
.chart-toolbar { display:flex; align-items:center; gap:10px; padding: 10px 14px; border-bottom: 1px solid var(--line); overflow:auto; }
.pair-title { display:flex; align-items:center; gap:10px; min-width:max-content; font-weight:850; }
.timeframes { display:flex; gap:4px; margin-left:12px; }
.tf { border: 0; border-radius: 7px; background: transparent; color: var(--muted); padding: 7px 9px; cursor:pointer; font-family:var(--mono); font-weight:800; }
.tf.active { background: rgba(41,98,255,.24); color: #fff; }
.big-chart { position: relative; overflow: hidden; background: repeating-linear-gradient(0deg, transparent 0 55px, rgba(255,255,255,.055) 56px), repeating-linear-gradient(90deg, transparent 0 76px, rgba(255,255,255,.04) 77px); }
.big-chart .price-label { position:absolute; right:12px; top:26%; background:var(--red); color:#fff; padding:5px 9px; border-radius:7px; font-family:var(--mono); font-weight:850; }
.chart-status { position:absolute; left:16px; top:14px; display:flex; gap:10px; align-items:center; color:var(--muted); }
.candle-layer { position:absolute; inset: 40px 34px 26px 22px; }
.financial-panel { border-top: 1px solid var(--line); display:grid; grid-template-columns: 1fr 1fr; min-height:0; }
.fin-card { padding: 12px 14px; border-right: 1px solid var(--line); overflow:auto; }
.side-panel { border-left: 1px solid var(--line); background: #111524; overflow: auto; }
