.side-title { display:flex; justify-content:space-between; align-items:center; padding: 12px 13px; font-weight:850; cursor:pointer; background:rgba(255,255,255,.025); }
.side-title::after { content:'▾'; color:var(--muted); transition:.18s; }.side-section.collapsed .side-title::after{transform:rotate(-90deg)}.side-section.collapsed .side-body{display:none}
.watch-row { display:grid; grid-template-columns: 64px 1fr 70px 64px; gap:8px; padding:9px 13px; border-top:1px solid rgba(255,255,255,.045); align-items:center; font-family:var(--mono); font-size:12px; }
.stock-detail { padding: 14px; }
.detail-price { font-family:var(--mono); font-size:32px; font-weight:900; margin: 6px 0 0; }
