/* Markets/Brokers */
.asset-nav { position: sticky; top: 65px; z-index: 30; background: rgba(15,15,15,.88); backdrop-filter: blur(14px); border-bottom: 1px solid var(--line); padding: 10px 0; }
.section-anchor { scroll-margin-top: 126px; }
